// Regenerates kanji-data.js. Run by hand when a source list changes; the app
// itself has no build step and ships the generated file as committed source.
//
//   npm i --no-save joyo-kanji kyoiku-kanji && node tools/build-kanji-data.mjs
//
// Both sources are MIT. Their notices are reproduced in the generated file,
// which is what MIT asks of us when we redistribute their data.
import {createRequire} from "node:module";
import {writeFileSync} from "node:fs";
const require = createRequire(import.meta.url);

const joyo = require("joyo-kanji").kanji;
const kyoiku = require("kyoiku-kanji");

// The generator asserts rather than warns. A list that has quietly changed
// shape should stop the build, not ship a wall with holes in it.
if (joyo.length !== 2136) throw new Error(`expected 2136 joyo kanji, got ${joyo.length}`);
if (new Set(joyo).size !== joyo.length) throw new Error("joyo list contains duplicates");

const grades = [];
for (let g = 1; g <= 6; g++) {
  const list = kyoiku["grade" + g];
  if (!Array.isArray(list) || !list.length) throw new Error(`grade${g} missing`);
  const stray = list.filter(k => !joyo.includes(k));
  if (stray.length) throw new Error(`grade${g} has kanji outside the joyo list: ${stray.join("")}`);
  grades.push(list.join(""));
}
const graded = new Set(grades.join(""));
if (graded.size !== 1006) throw new Error(`expected the 1,006 pre-2020 kyoiku kanji, got ${graded.size}`);

// The 2017 revision, in force from 2020, added these twenty prefecture kanji
// to the kyoiku list and took it to 1,026, redistributing grades 4-6. No
// source we have carries that new per-grade assignment, so they are named
// here rather than guessed at, and the grade bands stay as published before.
const PREFECTURE = "茨媛岡潟岐阜熊香佐埼崎滋鹿縄沖井栃奈梨阪";
const misplaced = [...PREFECTURE].filter(k => !joyo.includes(k));
if (misplaced.length) throw new Error(`prefecture kanji missing from joyo: ${misplaced.join("")}`);

const out = `// Generated by tools/build-kanji-data.mjs — do not edit by hand.
//
// The 2,136 joyo kanji (常用漢字表, 2010 cabinet notification) in their
// published order, and the kyoiku grade bands.
//
// Characters from joyo-kanji and kyoiku-kanji, both MIT licensed:
//   joyo-kanji   Copyright (c) Yuki Kodama — https://npm.im/joyo-kanji
//   kyoiku-kanji Copyright (c) Yuki Kodama — https://npm.im/kyoiku-kanji
// Permission is hereby granted, free of charge, to any person obtaining a copy
// of this software and associated documentation files (the "Software"), to deal
// in the Software without restriction. The Software is provided "as is",
// without warranty of any kind.

export const JOYO = ${JSON.stringify(joyo.join(""))};

// Index 0 is grade 1. These are the grades as published before the 2017
// revision: 1,006 characters. See PREFECTURE_2020 for what that leaves out.
export const GRADES = [
${grades.map(g => "  " + JSON.stringify(g) + ",").join("\n")}
];

// Kyoiku kanji since 2020 whose grade we cannot source. They sit in the
// last band until a list we trust says which of grades 4-6 each belongs to.
export const PREFECTURE_2020 = ${JSON.stringify(PREFECTURE)};
`;
writeFileSync(new URL("../kanji-data.js", import.meta.url), out);
console.log(`kanji-data.js: ${joyo.length} joyo, ${graded.size} graded, ${PREFECTURE.length} awaiting a grade`);
